arguments.rule_content:
{
  "title": "Suspicious Service Account Login from External IP",
  "id": "e3b0c442-91a4-4c5d-9f3e-8d6a9d5f1234",
  "description": "Detects authentication events where a privileged service account logs in from an IP address outside the corporate network range.",
  "status": "experimental",
  "author": "SOC Team",
  "logsource": {
    "product": "windows",
    "service": "security"
  },
  "detection": {
    "selection": {
      "EventID": 4624,
      "TargetUserName|contains": ["svc-backup", "svc-sql-prod"]
    },
    "filter_external_ip": {
      "IpAddress": "!10.0.0.0/8"
    },
    "condition": "selection and filter_external_ip"
  },
  "fields": ["TargetUserName", "IpAddress", "LogonType"],
  "falsepositives": ["Legitimate remote admin tasks"],
  "level": "high"
}
